create or replace function public.preview_match_correction(p_game_id integer)returns jsonb language sql security definer set search_path=public as $$
select jsonb_build_object('game',to_jsonb(g),'market',to_jsonb(m),'order_count',(select count(*) from orders where market_id=m.id),'position_count',(select count(*) from positions where market_id=m.id),'deletable',m.id is null or(not exists(select 1 from orders where market_id=m.id)and not exists(select 1 from positions where market_id=m.id))) from games g left join markets m on m.game_id=g.id where g.id=p_game_id;$$;
create or replace function public.admin_correct_match(p_operator_id uuid,p_game_id integer,p_action text,p_home_team_id integer,p_away_team_id integer,p_game_date date,p_game_time time,p_initial_price numeric,p_b numeric)
returns jsonb language plpgsql security definer set search_path=public as $$declare g games;m markets;impact jsonb;begin select * into g from games where id=p_game_id for update;if not found then raise exception '경기를 찾을 수 없습니다';end if;select * into m from markets where game_id=g.id for update;impact:=preview_match_correction(g.id);if m.status='SETTLED' then raise exception '정산 후 복구는 별도 워크플로우를 사용해주세요';end if;if m.id is not null and(exists(select 1 from orders where market_id=m.id)or exists(select 1 from positions where market_id=m.id))then raise exception '주문 또는 포지션이 있어 삭제/초기가 변경이 차단됩니다';end if;if upper(p_action)='DELETE'then if m.id is not null then delete from markets where id=m.id;end if;delete from games where id=g.id;elsif upper(p_action)='RECREATE'then if exists(select 1 from games where id<>g.id and game_date=p_game_date and home_team_id=p_home_team_id and away_team_id=p_away_team_id)then raise exception '중복 경기가 존재합니다. 병합 또는 취소를 선택해주세요';end if;if m.id is not null then delete from markets where id=m.id;end if;update games set home_team_id=p_home_team_id,away_team_id=p_away_team_id,game_date=p_game_date,game_time=p_game_time where id=g.id;insert into markets(game_id,b,status,season_id)values(g.id,p_b,'OPEN',(select id from seasons where status='ACTIVE'));else update games set home_team_id=p_home_team_id,away_team_id=p_away_team_id,game_date=p_game_date,game_time=p_game_time where id=g.id;end if;insert into admin_audit_logs(operator_id,action,target_type,target_id,before_state,after_state,success)values(p_operator_id,'MATCH_CORRECTION','game',p_game_id::text,impact,preview_match_correction(p_game_id),true);return impact;end;$$;
revoke all on function public.preview_match_correction(integer),public.admin_correct_match(uuid,integer,text,integer,integer,date,time,numeric,numeric) from public,anon,authenticated;grant execute on function public.preview_match_correction(integer),public.admin_correct_match(uuid,integer,text,integer,integer,date,time,numeric,numeric) to service_role;
